          onCancel={() => setEditing(null)}
          onSave={() => setEditing(null)}
          summary={
            <>
              <SummaryRow label="موبایل" value={data.mobile} ltr />
              <SummaryRow label="ایمیل" value={data.email} ltr />
            </>
          }
          form={
            <FieldGroup>
              <Field>
                <FieldLabel>موبایل</FieldLabel>
                <Input
                  value={data.mobile}
                  onChange={(e) =>
                    setData((d) => ({ ...d, mobile: e.target.value }))
                  }
                  dir="ltr"
                  className="text-start"
                />
              </Field>
              <Field>
                <FieldLabel>ایمیل</FieldLabel>
                <Input
                  type="email"
                  value={data.email}
                  onChange={(e) =>
                    setData((d) => ({ ...d, email: e.target.value }))
                  }
                  dir="ltr"
                  className="text-start"
                />
              </Field>
            </FieldGroup>
          }
        />
        <Separator />
        <SectionBlock
          title="مدرک هویتی"
          editing={editing === "document"}
          onEdit={() => setEditing("document")}
          onCancel={() => setEditing(null)}
          onSave={() => setEditing(null)}
          summary={<SummaryRow label="فایل" value={data.document} />}
          form={
            <Field>
              <FieldLabel>عنوان مدرک</FieldLabel>
              <Input
                value={data.document}
                onChange={(e) =>
                  setData((d) => ({ ...d, document: e.target.value }))
                }
              />
            </Field>
          }
        />
      </CardContent>
      <CardFooter>
        <Button
          className="w-full"
          disabled={editing !== null}
          onClick={() => setSubmitted(true)}
        >
          تأیید و ارسال نهایی
        </Button>
      </CardFooter>
    </Card>
  )
}

function SectionBlock({
  title,
  editing,
  onEdit,
  onCancel,
  onSave,
  summary,
  form,
}: {
  title: string
  editing: boolean
  onEdit: () => void
  onCancel: () => void
  onSave: () => void
  summary: React.ReactNode
  form: React.ReactNode
}) {
  return (
    <div className="py-4">
      <div className="mb-3 flex items-center justify-between gap-2">
        <h3 className="text-sm font-medium">{title}</h3>
        {!editing ? (
          <Button type="button" variant="ghost" size="sm" onClick={onEdit}>
            <PencilIcon />
            ویرایش
          </Button>
        ) : null}
      </div>
      {editing ? (
        <div className="space-y-4">
          {form}
          <div className="flex gap-2">
            <Button type="button" size="sm" onClick={onSave}>
              ذخیره
            </Button>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={onCancel}
            >
              انصراف
            </Button>
          </div>
        </div>
      ) : (
        <div className="space-y-2">{summary}</div>
      )}
    </div>
  )
}

function SummaryRow({
  label,
  value,
  ltr,
}: {
  label: string
  value: string
  ltr?: boolean
}) {
  return (
    <div className="flex items-center justify-between gap-3 text-sm">
      <span className="text-muted-foreground">{label}</span>
      <span className="font-medium" dir={ltr ? "ltr" : undefined}>
        {value}
      </span>
    </div>
  )
}

"use client"

import * as React from "react"
import { cn } from "cn"
import { CheckIcon, IdCardIcon } from "lucide-react"

const FA_DIGITS = "۰۱۲۳۴۵۶۷۸۹"
const EN_DIGITS = "0123456789"

function toFaDigits(value: string) {
  return value.replace(/\d/g, (digit) => FA_DIGITS[Number(digit)] ?? digit)
}

function toEnDigits(value: string) {
  return value.replace(/[۰-۹]/g, (digit) => {
    const index = FA_DIGITS.indexOf(digit)
    return index >= 0 ? EN_DIGITS[index] : digit
  })
}

/** Keep only Latin digits, max 10 (leading zero preserved as string). */
export function normalizeNationalId(value: string) {
  return toEnDigits(value).replace(/\D/g, "").slice(0, 10)
}

/** 3-6-1 grouping as printed on the card: ۰۰۱-۲۳۴۵۶۷-۸ */
export function formatNationalId(digits: string) {
  const d = normalizeNationalId(digits)
  const a = d.slice(0, 3)
  const b = d.slice(3, 9)
  const c = d.slice(9, 10)
  let out = a
  if (b) out += `-${b}`
  if (c) out += `-${c}`
  return toFaDigits(out)
}

/** Iranian national ID checksum (10 digits). */
export function isNationalId(digits: string) {
  const d = normalizeNationalId(digits)
  if (!/^\d{10}$/.test(d)) return false
  if (/^(\d)\1{9}$/.test(d)) return false

  let sum = 0
  for (let i = 0; i < 9; i++) {
    sum += Number(d[i]) * (10 - i)
  }
  const rem = sum % 11
  const check = Number(d[9])
  return rem < 2 ? check === rem : check === 11 - rem
}

